const getNeighborsForCountry = (countryId: string): string[] => {
  const neighbors = COUNTRY_BORDERS[countryId];
  if (neighbors && neighbors.length > 0) {
    return neighbors;
  }
  return ["usa", "china", "russia", "turkey", "egypt", "saudi_arabia"].filter(
    (id) => id !== countryId,
  );
};

