function generateHospitals(countryId: string, countryName: string) {
  const hospitalNames = [
    `مستشفى ${countryName} التخصصي الفائق`,
    `مجمع البشير الاستشفائي القومي بـ ${countryName}`,
    `مدينة الحسين الطبية العسكرية لـ ${countryName}`,
    `المستشفى الملكي للدراسات والطبابة بـ ${countryName}`,
    `مركز السلام والشفاء للطوارئ والإنقاذ`,
    `المجمع السرطاني والعلاجي المتطور بـ ${countryName}`,
    `مستشفى الرعاية والمكافحة الصحية المركزي`,
    `مستشفى الهلال الدولي للإغاثة والعمل الإنساني`,
    `المستشفى الجامعي الجديد والتكنولوجيا الكيميائية`,
    `المستشفى السيادي للطب والأمراض المستعصية`,
  ];
  return hospitalNames.map((name, index) => ({
    id: `${countryId}-hospital-${index + 1}`,
    name,
    health: 100,
    isActive: true,
  }));
}

