function initializeCabinet(countryId: string): CabinetMember[] {
  return CABINET_ROLES.map((role, index) => ({
    id: `cab-${countryId}-${index + 1}`,
    name: generateCabinetMemberName(countryId),
    role,
    status: "active",
    replacementCount: 0,
  }));
}

interface EconomicTierInfo {
  tier: number;
  title: string;
  minEconomy: number;
  perks: string;
}

function getEconomicTier(economy: number): EconomicTierInfo {
  if (economy >= 18000) {
    return {
      tier: 1,
      title: "القطب الأوحد والسيادة الاقتصادية المطلقة",
      minEconomy: 18000,
      perks:
        "انخفاض نسبة تضرر الاستقرار بنسبة 90%، مناعة تامة من العقوبات، وزيادة النفوذ النموي العام والمثالي.",
    };
  } else if (economy >= 8000) {
    return {
      tier: 2,
      title: "إمبراطورية اقتصادية كبرى",
      minEconomy: 8000,
      perks:
        "تقليص تأثير العقوبات بنسبة 70%، وحماية استباقية لاستقرار البلاد وزيادة الرضا الشعبي.",
    };
  } else if (economy >= 2000) {
    return {
      tier: 3,
      title: "عملاق اقتصادي قاري",
      minEconomy: 2000,
      perks:
        "تأثير إيجابي دائم على الرضا الشعبي وحماية تلقائية لـ 20% من عائدات المنافذ الاقتصادية.",
    };
  } else if (economy >= 500) {
    return {
      tier: 4,
      title: "قوة إقليمية مهيمنة",
      minEconomy: 500,
      perks:
        "زيادة الجاهزية العسكرية والقدرة التكنولوجية بـ 15% وتفوق تجاري ملحوظ.",
    };
  } else if (economy >= 100) {
    return {
      tier: 5,
      title: "قوة صاعدة ناشئة",
      minEconomy: 100,
      perks:
        "زيادة تدريجية وتلقائية للتبادل التجاري والاستثماري القومي ومصالح البلاد.",
    };
  } else {
    return {
      tier: 6,
      title: "دولة تحت التطوير المتسارع",
      minEconomy: 1,
      perks:
        "دعم ومساعدات مستمرة لمواجهة العقوبات وتطوير البنية الأساسية في الدولة.",
    };
  }
}

