function getTierBadgeStyle(tier: number): string {
  switch (tier) {
    case 1:
      return "bg-gradient-to-r from-amber-500 to-yellow-400 text-black font-black border border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)] px-3 py-1 rounded-lg text-xs flex items-center gap-1";
    case 2:
      return "bg-amber-500/20 text-amber-400 border border-amber-500/30 font-bold px-3 py-1 rounded-lg text-xs flex items-center gap-1";
    case 3:
      return "bg-purple-500/20 text-purple-400 border border-purple-500/30 font-bold px-3 py-1 rounded-lg text-xs flex items-center gap-1";
    case 4:
      return "bg-sky-500/20 text-sky-400 border border-sky-500/30 font-bold px-3 py-1 rounded-lg text-xs flex items-center gap-1";
    case 5:
      return "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-medium px-3 py-1 rounded-lg text-xs flex items-center gap-1";
    default:
      return "bg-slate-500/10 text-slate-400 border border-slate-500/20 px-3 py-1 rounded-lg text-xs flex items-center gap-1";
  }
}

