function generateAllStrategicRoads(): StrategicRoad[] {
  const roads: StrategicRoad[] = [];
  const roadTemplates = [
    {
      suffix: "الدولي السريع والممشي اللوجستي",
      desc: "شريان بري استراتيجي يربط عاصمة الدولة بحدودها الدولية، حاسم لنقل الإمدادات ونشر بطاريات الدفاع السريع والدبابات والمشاة.",
      speedLimit: 120,
      threatLevel: "high" as const,
      baseCars: 520,
      basePeds: 210,
    },
    {
      suffix: "الساحلي الرئيسي المفتوح",
      desc: "طريق محاذي للشواطئ يربط المناطق الاقتصادية بالمنافذ المائية، وتتحرك عليه ناقلات ومجموعات مارة بشكل مستمر.",
      speedLimit: 100,
      threatLevel: "medium" as const,
      baseCars: 410,
      basePeds: 340,
    },
    {
      suffix: "الدائري ومحور الحماية الأمنية",
      desc: "طريق دائري مخصص لربط الثكنات العسكرية بالمطارات والمنشآت الحيوية في عمق الدولة لتسيير التعزيزات وتأمين العاصمة.",
      speedLimit: 110,
      threatLevel: "high" as const,
      baseCars: 750,
      basePeds: 130,
    },
    {
      suffix: "الشرياني الأوسط للمدن",
      desc: "طريق رئيسي داخلي يربط الحواضر السكانية، يكثر فيه سفر المدنيين وسيارات الخدمات العامة وعموم المترجلين والعمال.",
      speedLimit: 90,
      threatLevel: "low" as const,
      baseCars: 850,
      basePeds: 720,
    },
    {
      suffix: "الحدودي المأهول للدوريات",
      desc: "ممر أمني يسلكه حرس الحدود والأرتال الخفيفة مع تواجد مستمر للمارة من السكان المحليين والمهربين وعابري التماس.",
      speedLimit: 80,
      threatLevel: "high" as const,
      baseCars: 120,
      basePeds: 90,
    },
    {
      suffix: "الرابط لمجمعات الطاقة والصناعة",
      desc: "طريق لوجستي مخصص لشاحنات الوقود وصهاريج النفط ونقل الغاز وسير فنيي التشغيل ومجموعات الطوارئ والعمال.",
      speedLimit: 95,
      threatLevel: "medium" as const,
      baseCars: 320,
      basePeds: 110,
    },
    {
      suffix: "البديل ومسار النزوح اللوجستي",
      desc: "ممر تعبئة جبلي أو صحراوي متعرج لتسيير حافلات التموين والسيارات العابرة والنازحين الفارين من مناطق الاستهداف الحاد.",
      speedLimit: 75,
      threatLevel: "low" as const,
      baseCars: 190,
      basePeds: 510,
    },
  ];

  INITIAL_COUNTRIES.forEach((country) => {
    roadTemplates.forEach((template, index) => {
      roads.push({
        id: `road-${country.id}-${index + 1}`,
        name: `طريق ${country.name} ${template.suffix}`,
        targetCountryId: country.id,
        carCount: Math.round(template.baseCars * (0.85 + Math.random() * 0.3)),
        pedestrianCount: Math.round(
          template.basePeds * (0.8 + Math.random() * 0.4),
        ),
        status: "normal",
        destructionLevel: 0,
        tacticalValue: template.desc,
        speedLimit: template.speedLimit,
        threatLevel: template.threatLevel,
      });
    });
  });

  return roads;
}

const INITIAL_ROADS: StrategicRoad[] = generateAllStrategicRoads();

function generateCaptiveName(countryId: string): string {
  const randElement = (arr: string[]) =>
    arr[Math.floor(Math.random() * arr.length)];
  switch (countryId) {
    case "sa":
    case "eg":
    case "qa":
    case "ae":
      return `${randElement(FIRST_NAMES_ARABIC)} ${randElement(LAST_NAMES_ARABIC)}`;
    case "usa":
      return `${randElement(FIRST_NAMES_USA)} ${randElement(LAST_NAMES_USA)}`;
    case "cn":
      return `${randElement(FIRST_NAMES_CN)} ${randElement(LAST_NAMES_CN)}`;
    case "ru":
      return `${randElement(FIRST_NAMES_RU)} ${randElement(LAST_NAMES_RU)}`;
    case "ir":
      return `${randElement(FIRST_NAMES_IR)} ${randElement(LAST_NAMES_IR)}`;
    case "il":
      return `${randElement(FIRST_NAMES_IL)} ${randElement(LAST_NAMES_IL)}`;
    default:
      return `${randElement(FIRST_NAMES_ARABIC)} ${randElement(LAST_NAMES_ARABIC)}`;
  }
}

